& {
    $ErrorActionPreference = 'Stop'
    $r = 'E:\Dev\uzdoom_src\doda-core'
    $tt = Join-Path $r 'generated\_tests_tmp'
    New-Item -ItemType Directory -Force -Path $tt | Out-Null
    $py = (Get-Command python -ErrorAction SilentlyContinue).Source
    if (-not $py) { $py = (Get-Command py -ErrorAction SilentlyContinue).Source }
    if (-not $py) { throw 'Python was not found.' }
    $env:TMP = $tt
    $env:TEMP = $tt
    $env:PYTHONDONTWRITEBYTECODE = '1'
    $pf = Join-Path $tt ('task_flow_preview_' + [guid]::NewGuid().ToString('N') + '.py')
    [System.IO.File]::WriteAllBytes($pf, [Convert]::FromBase64String(''))
    $marker = '=== COPY FROM HERE ==='
    Write-Host $marker -ForegroundColor Yellow
    $saved = $ErrorActionPreference
    try {
        $ErrorActionPreference = 'Continue'
        $output = @(& $py $pf $r 2>&1 | ForEach-Object { Write-Host "$_"; "$_" })
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $saved }
    $report = (@($marker) + $output + "Runner exit code: $code") -join "`r`n"
    try { Set-Clipboard -Value $report; Write-Host 'Report copied. Paste here with Ctrl+V.' } catch { Write-Warning 'Clipboard copy failed.' }
    if ($code -ne 0) { throw 'Patch stopped. Paste the report; do not rerun earlier patches.' }
    Remove-Item -LiteralPath $pf
}
